window.kbPageData["views/entry/k-33882f5ba374d7e3"] = {"key":"entry/k-33882f5ba374d7e3","state":{"route":"entry/k-33882f5ba374d7e3"},"node":{"id":"k-33882f5ba374d7e3","mode":"k","title":"凝结经验","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“凝结经验”的词语搭配","“经验”的含义及“凝结经验”的搭配"],"qs":["江苏 2024 A类 行测#36","江苏 2024 B类 行测#38"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"“凝结”用于抽象事物时，可以表示把长期积累的成果集中体现出来。“凝结经验”强调把实践所得集中体现在某一成果中。","review":{"definition":"“凝结”用于抽象事物时，可以表示把长期积累的成果集中体现出来。“凝结经验”强调把实践所得集中体现在某一成果中。","explanation":"第二空与“新理念”并列，句子说的是社会治理现代化集中体现了改革开放以来特别是新时代以来的治理实践积累。“新经验”突出实践所得，“新方法”偏重做法，“新举措”偏重行动，“新视野”偏重认识范围，因此本题选“新经验”。","references":[],"evidence":"凝结了改革开放以来特别是新时代以来我国社会治理的新理念","disposition":"独立词条","basis":"据原题和解析编释。","title":"凝结经验","related":[],"examFocus":{"江苏 2024 A类 行测#36":"判断第二空时，留意它既要能与“凝结”搭配，又要能与“新理念”并列。"}},"readings":[{"origin":"k-33882f5ba374d7e3","title":"凝结经验","qs":["江苏 2024 B类 行测#38"],"definition":"“凝结”用于抽象事物时，可以表示把长期积累的成果集中体现出来。“凝结经验”强调把实践所得集中体现在某一成果中。","explanation":"第二空与“新理念”并列，句子说的是社会治理现代化集中体现了改革开放以来特别是新时代以来的治理实践积累。“新经验”突出实践所得，“新方法”偏重做法，“新举措”偏重行动，“新视野”偏重认识范围，因此本题选“新经验”。","evidence":"凝结了改革开放以来特别是新时代以来我国社会治理的新理念","doubt":"","references":[]},{"origin":"k-5206f5199b993fe0","title":"凝结经验","qs":["江苏 2024 A类 行测#36"],"definition":"经验是在实践中获得的知识、技能或认识。“凝结经验”表示将实践所得积累并集中体现出来。","explanation":"题干中的“改革开放以来特别是新时代以来”交代了社会治理实践的时间跨度。“新理念、新经验”作“凝结了”的并列宾语，分别指治理观念和实践所得。“新方法”“新举措”侧重怎样做或采取了什么行动，“新视野”侧重看问题的范围，均较难贴合此处汇聚历年治理成果的语意。","evidence":"“经验”指从多次实践中得到的知识或技能，与“凝结”搭配恰当","doubt":"","references":[]}]},"questions":{"江苏 2024 A类 行测#36":{"paper":"江苏 2024 A类 行测","n":36,"mod":"言语理解与表达","src":["f8fec75f67d6d1ba5759.pdf",7],"asrc":["0126a1c8aceee632ea2b.pdf",11],"card":"1431400b8e5761f8c7d37120","links":[{"id":"k-33882f5ba374d7e3","role":"直接考查","why":"实践中形成的经验可作为“凝结”的宾语，与同句的“新理念”并列。"}]},"江苏 2024 B类 行测#38":{"paper":"江苏 2024 B类 行测","n":38,"mod":"言语理解与表达","src":["0ae7ac475476e5635bd7.pdf",7],"asrc":["8dd171daee6fc74e9718.pdf",13],"card":"f9ae9fcff939f0952dfb2095","links":[{"id":"k-33882f5ba374d7e3","role":"解题依据","why":"“经验”表示实践积累所得，与“凝结”构成第二空的关键搭配。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-33882f5ba374d7e3":[["江苏 2024 A类 行测#36","江苏 2024 B类 行测#38"]]}};
